<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt {{ $order->number }}</title><link rel="stylesheet" href="/app.css"><script src="/app.js" defer></script></head><body>
@php($money=fn($cents)=>$business->currency.' '.number_format($cents/100,2))
